import { describe, expect, it } from 'vitest'
import {
  generatedFromVersion,
  parseRequestEntries,
  reachableSchemas,
  resolveResponseTypeName,
  selectAllowed,
  UNRESOLVED_RESPONSE,
  versionMismatch,
} from './helpers.ts'

// Trimmed from codex-cli 0.172.0's `generate-ts` ClientRequest.ts. It publishes
// ModelProviderDefaultSetParams but no ModelProviderDefaultSetResponse, and names the
// account/securitySetup/read response GetAccountSecuritySetupResponse.
const clientRequest172 = `export type ClientRequest =
  { "method": "thread/start", id: RequestId, params: ThreadStartParams, } |
  { "method": "account/logout", id: RequestId, params: undefined, } |
  { "method": "account/securitySetup/read", id: RequestId, params: undefined, } |
  { "method": "modelProvider/default/set", id: RequestId, params: ModelProviderDefaultSetParams, };`

const schemaNames172 = new Set([
  'V2ThreadStartParams',
  'V2ThreadStartResponse',
  'V2LogoutAccountResponse',
  'V2GetAccountSecuritySetupResponse',
  'V2ModelProviderDefaultSetParams',
])

describe('response schemas', () => {
  it('types a method with no response schema as any JSON instead of failing', () => {
    const responses = parseRequestEntries(clientRequest172).map((entry) => [
      entry.method,
      resolveResponseTypeName(entry.method, entry.paramsType, schemaNames172),
    ])
    expect(responses).toEqual([
      ['thread/start', 'V2ThreadStartResponse'],
      ['account/logout', 'V2LogoutAccountResponse'],
      ['account/securitySetup/read', 'V2GetAccountSecuritySetupResponse'],
      ['modelProvider/default/set', UNRESOLVED_RESPONSE],
    ])
  })
})

describe('--check version gate', () => {
  const meta = `// This file is generated by the effect-codex-app-server package. Do not edit manually.
// Generator vendored from T3 Code (MIT, Copyright (c) 2026 T3 Tools Inc.); see THIRD_PARTY_NOTICES.md.
// Generated from: codex-cli 0.167.1

import * as CodexSchema from "./schema.gen.ts";`

  it('names both versions when the installed CLI differs', () => {
    expect(generatedFromVersion(meta)).toBe('codex-cli 0.167.1')
    expect(versionMismatch(generatedFromVersion(meta), 'codex-cli 0.172.0')).toBe(
      'Codex protocol schemas are for codex-cli 0.167.1, installed codex-cli 0.172.0. Run `pnpm protocol`.',
    )
  })

  it('passes the same version on, and stops when the header is missing', () => {
    expect(versionMismatch('codex-cli 0.167.1', 'codex-cli 0.167.1')).toBeNull()
    expect(versionMismatch(generatedFromVersion(''), 'codex-cli 0.172.0')).toContain('an unknown codex-cli')
  })
})

describe('allowlist filter', () => {
  it('keeps the allowlisted methods in CLI order, and fails on one the CLI dropped', () => {
    const entries = parseRequestEntries(clientRequest172)
    expect(selectAllowed('client requests', entries, ['account/logout', 'thread/start'])).toEqual([
      entries[0],
      entries[1],
    ])
    expect(() => selectAllowed('client requests', entries, ['thread/start', 'thread/read'])).toThrow(
      'Allowlisted client requests this codex-cli does not publish: thread/read',
    )
  })

  it('follows refs from the roots and leaves unreached schemas out', () => {
    const ref = (name: string) => ({ $ref: `#/components/schemas/${name}` })
    const schemas = {
      Params: { type: 'object', properties: { item: ref('Item'), list: { items: [ref('Leaf')] } } },
      Item: { anyOf: [ref('Leaf'), ref('Item')] },
      Leaf: { type: 'string' },
      Unused: { properties: { leaf: ref('Leaf') } },
    }
    expect([...reachableSchemas(['Params'], schemas)].toSorted()).toEqual(['Item', 'Leaf', 'Params'])
    expect(() => reachableSchemas(['Missing'], schemas)).toThrow('Unable to resolve schema: Missing')
  })
})
